select public.person_denied($q$select public.admin_remove_family_member('10000000-0000-0000-0000-000000000020','10000000-0000-0000-0000-000000000015','MEMBER',current_setting('test.member_stamp')::timestamptz,'Managed corrected','Family 20','Support correction')$q$,'23514');
reset role;
